/**
 * Film 9 uses the same two exact canonical donor profiles as Bicycle Thieves,
 * but with the reversed partial/miss order. Reuse their vetted long translations
 * and fingerprint metadata rather than duplicating historical statements.
 */
const bicycleThievesDonors = SOURCE_LOCKED_DONOR_CHOICES.scenario_bicycle_thieves_1948;
if (!bicycleThievesDonors?.partial || !bicycleThievesDonors?.miss) {
  throw new Error("Missing source-locked Bicycle Thieves historical donor texts");
}
export const FILM_STUDY_VERIFIED_DONOR_CHOICES: Readonly<
  Record<string, Partial<Record<"partial" | "miss", DonorChoice>>>
> = {
  ...SOURCE_LOCKED_DONOR_CHOICES,
  scenario_the_shining_1980: {
    partial: bicycleThievesDonors.miss, // Oppenheimer (2023)
    miss: bicycleThievesDonors.partial, // About Dry Grasses (2023)
  },
};

export function canonicalFilmStudyOptionFingerprint(value: string): { readonly length: number; readonly hash: number } {
  let hash = 0;
  for (let index = 0; index < value.length; index += 1) {
    hash = (hash * 31 + value.charCodeAt(index)) >>> 0;
  }
  return { length: value.length, hash };
}

export function presentVerifiedFilmStudyDonorChoice(
  language: FilmWorkLanguage,
  targetScenarioId: string,
  quality: "match" | "partial" | "miss",
  canonicalOption: string,
): string {
  if (language === "en" || quality === "match") return canonicalOption;
  const entry = FILM_STUDY_VERIFIED_DONOR_CHOICES[targetScenarioId]?.[quality];
  if (!entry) return canonicalOption;
  const fingerprint = canonicalFilmStudyOptionFingerprint(canonicalOption);
  return fingerprint.length === entry.canonicalLength && fingerprint.hash === entry.canonicalHash
    && canonicalOption.startsWith(entry.preview)
    ? entry.text[language]
    : canonicalOption;
}

/**
 * Short option label for source-locked donor alternatives.
 * A changed donor label never receives a stale synopsis.
 * The complete source-matched explanation remains available through the
 * adjacent disclosure and is always used for the real quiz.
 */
export function presentVerifiedFilmStudyDonorChoiceSummary(
  language: FilmWorkLanguage,
  targetScenarioId: string,
  quality: "match" | "partial" | "miss",
  canonicalOption: string,
): string | undefined {
  if (quality === "match") return undefined;
  const entry = FILM_STUDY_VERIFIED_DONOR_CHOICES[targetScenarioId]?.[quality];
  if (!entry || !canonicalOption.startsWith(entry.preview)) return undefined;
  const fingerprint = canonicalFilmStudyOptionFingerprint(canonicalOption);
  if (fingerprint.length !== entry.canonicalLength || fingerprint.hash !== entry.canonicalHash) return undefined;
  return entry.summary[language];
}
